export type DiscoveryKind = 'memory' | 'note' | 'tool' | 'skill' | 'mcp' | 'ssh' | 'design' | 'database';
export type FileKind = 'notes' | 'tools' | 'skills' | 'mcp' | 'ssh' | 'design' | 'databases';
export type DiscoveryPlace = { id: string; name: string; path: string; kind: 'home' | 'drive' | 'folder' | 'added'; state: 'allow' | 'exclude' | null; inherited: 'allow' | 'exclude' | null; hasChildren: boolean };
export type MergeSuggestion = { key: string; a: { id: string; name: string }; b: { id: string; name: string }; reason: string };
export type DiscoveryState = 'new' | 'changed' | 'decision' | 'imported' | 'ignored' | 'gone';
export type DiscoveryItem = { id: string; kind: DiscoveryKind; name: string; from: string; rootId: string | null; to: string; state: DiscoveryState; updatedAt: string };
export type DiscoveryRoot = { id: string; name: string; path: string | null; project: string | null; count: number; fresh: number; watch: boolean; group?: { members: { id: string; name: string; path: string }[] }; hidden?: DiscoveryKind[] };
export type DiscoverySettings = { watch: boolean; intervalMinutes: 15 | 30 | 60; kinds: Record<FileKind, boolean> };
export type DiscoveryView = { scannedAt: string | null; ms: number; leftOut: number; allowedFolders: number; suggestions: MergeSuggestion[]; settings: DiscoverySettings; roots: DiscoveryRoot[]; items: DiscoveryItem[] };
export type DiscoveryPreview = { id: string; kind: DiscoveryKind; name: string; from: string; to: string; state: DiscoveryState; text: string; truncated: boolean; secrets: string[]; blocked: string | null; previewHash: string };
export type DiscoveryResult = { id: string; ok: boolean; state?: DiscoveryState; code?: string; jobId?: string };
export const DISCOVERY_PATH: '/api/memory/import/discovery';
export const DISCOVERY_KINDS: readonly DiscoveryKind[];
export const DISCOVERY_STATES: readonly DiscoveryState[];
export const FILE_KINDS: readonly FileKind[];
export const MAX_DISCOVERY_IMPORT: number;
export function discoveryPath(path: string): { kind: string; id?: string } | null;
export function discoveryRoute(path: string): boolean;
export function allowedDiscovery(method: string, path: string, body?: unknown): boolean;
export function discoveryResponse(path: string, status: number, body: unknown): unknown;
